function classify(name,mime=''){const e=name.split('.').pop().toLowerCase();if(e==='pdf'||mime==='application/pdf')return'pdf';if(['epub','mobi','azw','azw3','fb2'].includes(e))return'books';if(['mp3','m4a','aac','flac','wav','ogg','opus','wma','aiff'].includes(e)||mime.startsWith('audio/'))return'music';if(['mp4','webm','mov','mkv','avi','m4v','mpg','mpeg'].includes(e)||mime.startsWith('video/'))return'video';if(['jpg','jpeg','png','webp','gif','avif','heic','bmp','svg','tif','tiff'].includes(e)||mime.startsWith('image/'))return'photos';if(['doc','docx','xls','xlsx','csv','ppt','pptx','odt','ods','odp'].includes(e))return'office';return'other';}
