let pendingWrites=[],pendingSequence=0,pendingRetrying=false;try{pendingWrites=JSON.parse(localStorage.getItem('luliy-drive-pending')||'[]');if(!Array.isArray(pendingWrites))pendingWrites=[];pendingWrites.forEach(item=>Object.values(item.versions||{}).forEach(version=>pendingSequence=Math.max(pendingSequence,Number(version)||0)));}catch{}
function persistPending(){try{localStorage.setItem('luliy-drive-pending',JSON.stringify(pendingWrites.slice(-100)));}catch{}}
function settlePending(user,key,patch,versions={}){let changed=false;for(const item of pendingWrites){if(item.user!==user||item.key!==key)continue;for(const field of Object.keys(patch)){if(!Object.hasOwn(item.patch||{},field))continue;const queued=Number(item.versions?.[field])||0,sent=Number(versions[field])||0;if(queued<=sent){delete item.patch[field];if(item.versions)delete item.versions[field];changed=true;}}}pendingWrites=pendingWrites.filter(item=>Object.keys(item.patch||{}).length);if(changed)persistPending();}
function queuePending(user,key,patch,versions){let item=pendingWrites.find(p=>p.user===user&&p.key===key);if(!item){item={user,key,patch:{},versions:{}};pendingWrites.push(item);}item.versions||={};for(const field of Object.keys(patch)){const version=Number(versions[field])||0;if(version>=(Number(item.versions[field])||0)){item.patch[field]=patch[field];item.versions[field]=version;}}persistPending();}
async function retryPending(s){if(pendingRetrying||s.mode!=='live'||!s.me?.personal||!s.me.userId)return;pendingRetrying=true;try{for(const item of [...pendingWrites]){if(item.user!==s.me.userId)continue;const patch={...item.patch},versions={...item.versions};try{await post('state',{key:item.key,...patch},'PATCH');settlePending(item.user,item.key,patch,versions);}catch(e){if(e.status===404){pendingWrites=pendingWrites.filter(p=>p!==item);persistPending();}else break;}}}finally{pendingRetrying=false;}}
