async function signedHeaders(url,opts={}){
 const encoder=new TextEncoder(),hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''),sha=async b=>hex(await crypto.subtle.digest('SHA-256',b));
 const mac=async(k,v)=>{const key=await crypto.subtle.importKey('raw',typeof k==='string'?encoder.encode(k):k,{name:'HMAC',hash:'SHA-256'},false,['sign']);return crypto.subtle.sign('HMAC',key,encoder.encode(v));};
 const date=new Date().toISOString().replace(/[:-]|\.\d{3}/g,''),day=date.slice(0,8),scope=day+'/us-east-1/s3/aws4_request';
 const payload=opts.body instanceof Blob?await opts.body.arrayBuffer():encoder.encode(opts.body||''),hash=await sha(payload),escape=v=>encodeURIComponent(v).replace(/[!'()*]/g,c=>'%'+c.charCodeAt(0).toString(16).toUpperCase());
 const query=[...url.searchParams].map(([k,v])=>[escape(k),escape(v)]).sort((a,b)=>a[0]<b[0]?-1:a[0]>b[0]?1:a[1]<b[1]?-1:a[1]>b[1]?1:0).map(p=>p.join('=')).join('&'),names='host;x-amz-content-sha256;x-amz-date';
 const canonical=[opts.method||'GET',url.pathname,query,'host:'+url.host+'\nx-amz-content-sha256:'+hash+'\nx-amz-date:'+date+'\n',names,hash].join('\n');
 let key=await mac('AWS4'+credentials.secret,day);key=await mac(key,'us-east-1');key=await mac(key,'s3');key=await mac(key,'aws4_request');const signature=hex(await mac(key,'AWS4-HMAC-SHA256\n'+date+'\n'+scope+'\n'+await sha(encoder.encode(canonical))));
 return {'X-Amz-Date':date,'X-Amz-Content-Sha256':hash,Authorization:'AWS4-HMAC-SHA256 Credential='+credentials.access+'/'+scope+', SignedHeaders='+names+', Signature='+signature};
}
async function request(path,opts={},anonymous=false){
 const u=new URL(ENDPOINT+'/api/drive/'+path),headers={...opts.headers};if(!anonymous){if(sessionToken)headers.Authorization='Bearer '+sessionToken;else if(credentials)Object.assign(headers,await signedHeaders(u,opts));else throw Error(t('登入已失效，請重新連接。'));}
 const r=await fetch(u,{...opts,headers,signal:opts.signal||AbortSignal.timeout(30000)});let data;try{data=await r.json();}catch{throw Error('服務回應無效（'+r.status+'）');}if(!r.ok){if(r.status===401&&!anonymous){clearMediaIdentity();sessionToken='';credentials=null;clearSavedLogin();if(active&&!active.dead){stopAudio(active);resetIdentityView(active);active.mode='locked';active.me={personal:false,permission:'readonly'};updateMode(active);showGate(active);}}throw Object.assign(Error(r.status===401?t('登入已失效，請重新連接。'):data.error||'服務錯誤 '+r.status),{status:r.status});}return data;
}
const post=(path,data,method='POST')=>request(path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function demoItem(o){const s=demo.states.get(o.key)||{};return {...o,favorite:s.favorite??o.favorite,category:s.category===undefined?o.category:s.category||classify(o.name,o.content_type),progress:s.progress,bookmarks:JSON.stringify(s.bookmarks||[]),preview_key:s.previewKey};}
function demoQuery(s){let rows=demo.files.map(demoItem);const groups={media:['music','video'],docs:['office','pdf','books']};if(s.q)rows=rows.filter(o=>o.key.toLowerCase().includes(s.q.toLowerCase()));if(s.folder)rows=rows.filter(o=>o.key.startsWith(s.folder));if(s.favorite||s.category==='favorites')rows=rows.filter(o=>o.favorite);else if(s.category==='recent')rows=rows.filter(o=>Date.now()-Date.parse(o.last_modified)<30*86400000);else if(!['all','folders','playlists'].includes(s.category))rows=rows.filter(o=>(groups[s.category]||[s.category]).includes(o.category));if(s.playlist)rows=rows.filter(o=>s.playlist.keys.includes(o.key));rows.sort((a,b)=>s.sort==='name'?a.name.localeCompare(b.name):s.sort==='size'?b.size-a.size:Date.parse(b.last_modified)-Date.parse(a.last_modified));return rows;}
