async function playlists(s,render=false){
 const lists=s.mode==='demo'?demo.playlists.map(p=>({...p,items:p.keys.map(k=>demo.files.find(f=>f.key===k)).filter(Boolean).map(demoItem)})):await request('playlists');if(s.dead)return lists;s.playlists=lists;
 if(render){s.folderList.replaceChildren();const create=button('建立歌單',null,'music');create.disabled=s.mode!=='demo'&&!s.me?.personal;create.onclick=async()=>{try{const r=await ask(s,'建立歌單',[{label:'名稱',name:'name'}]);if(!r)return;if(s.mode==='demo'){demo.playlists.push({id:crypto.randomUUID(),name:r.name,keys:[]});saveDemo();}else await post('playlists',{name:r.name});await playlists(s,true);}catch(e){notice(s,e.message,true);}};s.folderList.append(create);
  function show(p){s.playlist=p;const query=s.q.toLowerCase();s.items=p.items.filter(o=>!query||o.key.toLowerCase().includes(query));s.total=s.items.length;renderFiles(s);s.title.textContent=p.name;s.counter.textContent=s.total+' '+t('個檔案');s.more.hidden=true;if(!s.items.length)empty(s);s.folderList.querySelector('.ld-playlist-actions')?.remove();const actions=node('div','ld-playlist-actions'),playAll=button('播放全部',null,'play'),manage=button('管理歌單');playAll.onclick=()=>{const queue=p.items.filter(f=>f.readable&&Number(f.size)<=MAX&&musicCanPlay(f)&&classify(f.name,f.content_type)==='music');if(queue.length)play(s,queue[0],p.items);else notice(s,'歌單沒有可播放歌曲。',true);};manage.disabled=s.mode!=='demo'&&!s.me?.personal;manage.onclick=()=>managePlaylist(s,p);actions.append(playAll,manage);s.folderList.append(actions);}
  for(const p of lists){const b=button(p.name+' · '+p.items.length,null,'music',null,true);b.onclick=()=>show(p);s.folderList.append(b);}if(s.playlist){const current=lists.find(p=>p.id===s.playlist.id);if(current)show(current);else s.playlist=null;}
 }return lists;
}
async function addPlaylist(s,o){let lists=await playlists(s);if(!lists.length){const r=await ask(s,'建立歌單',[{label:'名稱',name:'name'}]);if(!r)return;if(s.mode==='demo'){demo.playlists.push({id:crypto.randomUUID(),name:r.name,keys:[]});saveDemo();}else await post('playlists',{name:r.name});lists=await playlists(s);}const r=await ask(s,'加入歌單',[{label:'我的歌單',name:'id',options:lists.map(p=>[p.id,p.name])}]);if(!r)return;const list=lists.find(p=>p.id===r.id),keys=[...new Set([...list.items.map(f=>f.key),o.key])];if(s.mode==='demo'){demo.playlists.find(p=>p.id===r.id).keys=keys;saveDemo();}else await post('playlists',{id:r.id,keys},'PATCH');notice(s,'已加入歌單。');}
