function thumbCanvas(source,width,height){if(!width||!height||width*height>16000000)throw Error('Image too large');const c=node('canvas'),scale=Math.min(1,320/Math.max(width,height));c.width=Math.max(1,Math.round(width*scale));c.height=Math.max(1,Math.round(height*scale));c.getContext('2d').drawImage(source,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.72);}
