function queueRender(s){s.uploadQueue.replaceChildren();s.uploadQueue.hidden=!s.uploads.length;if(!s.uploads.length)return;s.uploadQueue.append(node('h3','','上傳佇列'));for(const item of s.uploads){const row=node('div','ld-upload-row'),name=node('span','ld-raw',item.file.name),state=node('small','',t(item.state)+(item.error?' · '+item.error:'')),progress=node('progress');progress.max=100;progress.value=item.progress;name.append(state);const control=button(item.state==='失敗'||item.state==='已取消'?'重試':item.state==='成功'?'關閉':'取消');control.setAttribute('aria-label',item.state==='成功'?'關閉 '+item.file.name:item.state==='失敗'||item.state==='已取消'?'重試 '+item.file.name:'取消 '+item.file.name);control.onclick=()=>{if(item.state==='成功'){clearTimeout(item.dismissTimer);s.uploads=s.uploads.filter(i=>i!==item);queueRender(s);}else if(item.state==='失敗'||item.state==='已取消'){clearTimeout(item.dismissTimer);item.state='等待';item.cancelled=false;item.error='';item.progress=0;runUploads(s);queueRender(s);}else{item.cancelled=true;item.xhr?.abort();item.state='已取消';queueRender(s);}};row.append(name,progress,control);if(item.state==='失敗'||item.state==='已取消'){const close=button('關閉');close.setAttribute('aria-label','關閉 '+item.file.name);close.onclick=()=>{s.uploads=s.uploads.filter(i=>i!==item);queueRender(s);};row.append(close);}if(item.state==='成功'&&(classify(item.key,item.file.type)==='music'||/\.(pdf|epub|txt)$/i.test(item.key))){const kind=classify(item.key,item.file.type)==='music'?'record':'book',add=button(kind==='record'?'加入唱片':'加入書房');add.disabled=s.mode==='live'&&!s.me.personal;add.onclick=async()=>{try{const o=s.mode==='demo'?demo.files.find(f=>f.key===item.key):{...await request('object?key='+encodeURIComponent(item.key)),name:item.key.split('/').pop()};await editCollection(s,o,kind);}catch(e){notice(s,e.message,true);}};row.append(add);}s.uploadQueue.append(row);}}
